            C++

    #include <iostream>
using namespace std;

int maxProduct(int n)
{
    // Base Cases
    // Rope of length 2 or 3
    // must be cut at least once
    if (n == 2 || n == 3)
    {
        return n - 1;
    }

    // Store final product
    int product = 1;

    // Keep cutting parts of length 3
    // while remaining length is greater than 4
    while (n > 4)
    {
        // Multiply current product by 3
        product *= 3;

        // Reduce rope length
        n -= 3;
    }

    // Multiply remaining rope length
    return product * n;
}

